userDefinedLinkHintCss:
/* isekai: source ~/.config/nvim/lua/palette.lua (M.isekai) */

:root {
  --vimium-background-color: #0E1116 !important;      /* base */
  --vimium-background-text-color: #A3A7B5 !important; /* text */
  --vimium-foreground-color: #060809 !important;      /* mantle */
  --vimium-foreground-text-color: #A3A7B5 !important; /* text */
  --vimium-link-color: #6C94C9 !important;            /* blue */
}

/* Link hints */
div > .vimiumHintMarker {
  background: #2B2E3B !important;           /* visual */
  border: 1px solid #4F5162 !important;     /* comment */
  box-shadow: none !important;
}
div > .vimiumHintMarker span {
  color: #F9E2AF !important;                /* yellow_bright */
  text-shadow: none !important;
}
div > .vimiumHintMarker > .matchingCharacter {
  color: #4F5162 !important;                /* comment */
}
div > .vimiumActiveHintMarker span {
  color: #FFAC81 !important;                /* orange_bright */
}

/* Vomnibar */
#vomnibar {
  background: #0E1116 !important;           /* base */
  color: #A3A7B5 !important;                /* text */
  border: 1px solid #242438 !important;     /* border */
}
#vomnibar-search-area {
  border-bottom: 1px solid #242438 !important; /* border */
}
#vomnibar input {
  background-color: #060809 !important;     /* mantle */
  color: #A3A7B5 !important;                /* text */
  border: none !important;
  box-shadow: none !important;
}
#vomnibar input::selection {
  background-color: #2B2E3B !important;     /* visual */
  color: #D8D9E0 !important;                /* white */
}
#vomnibar li {
  border-bottom: 1px solid #242438 !important; /* border */
}
#vomnibar li.selected {
  background-color: #2B2E3B !important;     /* visual */
}
#vomnibar li em,
#vomnibar li .title {
  color: #A3A7B5 !important;                /* text */
}
#vomnibar li .url {
  color: #6C94C9 !important;                /* blue */
}
#vomnibar li .source {
  color: #4F5162 !important;                /* comment */
}
#vomnibar li .match,
#vomnibar li em .match,
#vomnibar li .title .match {
  color: #D0C093 !important;                /* yellow */
}

/* HUD (find mode, messages) */
#hud-container {
  background-color: #0E1116 !important;     /* base */
  color: #A3A7B5 !important;                /* text */
  border: 1px solid #242438 !important;     /* border */
}
#hud-body,
#hud.hud-find {
  background-color: #0E1116 !important;     /* base */
  border: none !important;
}
span#hud-match-count {
  color: #4F5162 !important;                /* comment */
}
